style.css:
@-moz-document domain("wattpad.com") {
:root {
    --paper: #C6A477;
    --paper-light: #D6B78D;
    --search-bg: #E0C49A;
    --text-brown: #4A3021;
    --border-brown: #AD895C;
    --accent-brown: #80552B;
  }

  /* NỀN TOÀN TRANG */
  html,
  body,
  #app,
  #root,
  main,
  [id="app"] {
    background: var(--paper) !important;
    color: var(--text-brown) !important;
  }

  /* HEADER VÀ THANH ĐIỀU HƯỚNG */
  header,
  nav,
  footer,
  [role="banner"],
  [role="navigation"],
  [class*="header"],
  [class*="Header"],
  [class*="navbar"],
  [class*="Navbar"],
  [class*="navigation"],
  [class*="Navigation"],
  [class*="top-bar"],
  [class*="topBar"] {
    background-color: var(--paper) !important;
    color: var(--text-brown) !important;
  }

  /* KHUNG NỘI DUNG VÀ VÙNG ĐỌC TRUYỆN */
  main,
  article,
  section,
  [role="main"],
  [class*="reading"],
  [class*="Reading"],
  [class*="chapter"],
  [class*="Chapter"],
  [class*="story-content"],
  [class*="storyContent"],
  [class*="story-body"],
  [class*="storyBody"] {
    background-color: var(--paper) !important;
    color: var(--text-brown) !important;
  }

  /* TIÊU ĐỀ VÀ NỘI DUNG CHỮ */
  h1, h2, h3, h4, h5, h6,
  p, li, span, label,
  [class*="title"],
  [class*="Title"],
  [class*="description"],
  [class*="Description"] {
    color: var(--text-brown) !important;
  }

  /* CHỮ TRONG TRUYỆN */
  [class*="reading"] p,
  [class*="chapter"] p,
  [class*="story-content"] p,
  [class*="storyContent"] p,
  [class*="story-body"] p,
  [class*="storyBody"] p {
    color: var(--text-brown) !important;
    line-height: 1.9 !important;
  }

  /* THANH TÌM KIẾM */
  input,
  input[type="search"],
  [role="search"] input,
  [class*="search"] input,
  [class*="Search"] input,
  [class*="search-bar"],
  [class*="searchBar"] {
    background-color: var(--search-bg) !important;
    color: var(--text-brown) !important;
    border-color: var(--border-brown) !important;
  }

  input::placeholder {
    color: var(--accent-brown) !important;
    opacity: 1 !important;
  }

  /* Ô NHẬP VÀ MENU */
  textarea,
  select,
  [role="menu"],
  [role="dialog"],
  [role="listbox"] {
    background-color: var(--paper-light) !important;
    color: var(--text-brown) !important;
    border-color: var(--border-brown) !important;
  }

  /* THẺ SÁCH VÀ KHUNG GỢI Ý */
  [class*="card"],
  [class*="Card"],
  [class*="panel"],
  [class*="Panel"],
  [class*="container"],
  [class*="Container"],
  [class*="wrapper"],
  [class*="Wrapper"] {
    background-color: var(--paper) !important;
    color: var(--text-brown) !important;
  }

  /* LIÊN KẾT VÀ NÚT */
  a {
    color: var(--accent-brown) !important;
  }

  button {
    color: var(--text-brown);
    border-color: var(--border-brown);
  }

  /* ĐƯỜNG VIỀN */
  hr {
    border-color: var(--border-brown) !important;
  }

  /* GIỮ NGUYÊN MÀU ẢNH BÌA VÀ HÌNH MINH HỌA */
  img,
  video,
  picture,
  canvas {
    filter: none !important;
  }
  
/* ===== ĐỒNG BỘ KHUNG BÌNH LUẬN WATTPAD ===== */

/* Màu nền cho khung bình luận và các vùng chứa */
body,
body #app,
body [role="dialog"],
body [role="dialog"] > div,
body [class*="comment"],
body [class*="Comment"],
body [class*="modal"],
body [class*="Modal"],
body [class*="drawer"],
body [class*="Drawer"] {
    background-color: #C6A477 !important;
    color: #4A3021 !important;
}

/* Khung nhập bình luận */
body textarea,
body input,
body [contenteditable="true"] {
    background-color: #E0C49A !important;
    color: #4A3021 !important;
    border-color: #B89567 !important;
}

/* Chữ gợi ý trong ô nhập */
body textarea::placeholder,
body input::placeholder {
    color: #806044 !important;
    opacity: 1 !important;
}

/* Nội dung bình luận */
body [class*="comment"] p,
body [class*="Comment"] p {
    color: #4A3021 !important;
}

/* Giữ màu nâu cho các vùng trắng thường gặp */
body [class*="panel"],
body [class*="Panel"],
body [class*="container"],
body [class*="Container"] {
    background-color: #C6A477 !important;
}

/* Thanh tiêu đề khung bình luận */
body [class*="header"],
body [class*="Header"] {
    background-color: #C6A477 !important;
    color: #4A3021 !important;
}
  
/* ===== WATTPAD BROWN - FIX BACKGROUND ===== */

:root {
    --brown-bg: #C6A477;
    --brown-panel: #D2B48C;
    --brown-search: #E0C49A;
    --brown-text: #4A3021;
}

/* Nen trang va cac khu vuc chinh */
html,
body,
#app,
main,
[role="main"] {
    background-color: var(--brown-bg) !important;
    color: var(--brown-text) !important;
}

/* Thanh dau trang va thanh dieu huong */
header,
nav,
[role="banner"],
[class*="header"],
[class*="Header"],
[class*="navbar"],
[class*="Navbar"],
[class*="navigation"],
[class*="Navigation"] {
    background-color: var(--brown-bg) !important;
    color: var(--brown-text) !important;
}

/* O tim kiem */
input,
input[type="search"],
[role="search"],
[role="searchbox"],
[class*="search"],
[class*="Search"] input {
    background-color: var(--brown-search) !important;
    color: var(--brown-text) !important;
}

/* Vung doc truyen */
[class*="story-content"],
[class*="StoryContent"],
[class*="reading"],
[class*="Reading"],
[class*="chapter-content"],
[class*="ChapterContent"] {
    background-color: var(--brown-bg) !important;
    color: var(--brown-text) !important;
}

/* Khung binh luan va cac bang noi dung */
[role="dialog"],
[role="complementary"],
[class*="comment-list"],
[class*="CommentList"],
[class*="comment-item"],
[class*="CommentItem"],
[class*="comment-body"],
[class*="CommentBody"] {
    background-color: var(--brown-panel) !important;
    color: var(--brown-text) !important;
}

/* O viet binh luan */
textarea,
[contenteditable="true"] {
    background-color: var(--brown-search) !important;
    color: var(--brown-text) !important;
}

/* Mau chu */
p,
h1, h2, h3, h4,
label {
    color: var(--brown-text);
}
 /* Thanh tên truyện */
#funbar {
    background-color: #B89568 !important;
    color: #4A3021 !important;
}

/* Chữ và liên kết bên trong thanh tên truyện */
#funbar *,
#funbar a,
#funbar span {
    color: #4A3021 !important;
}
  /* Khôi phục màu nâu cho nội dung bình luận */
.paragraph-content {
    background-color: #D2B48C !important;
    color: #4A3021 !important;
}

/* Nền khung bình luận */
[class*="comment"],
[class*="Comment"] {
    background-color: #D2B48C !important;
    color: #4A3021 !important;
}

/* Ô nhập bình luận */
textarea,
[contenteditable="true"] {
    background-color: #E0C49A !important;
    color: #4A3021 !important;
}
  /* Nút Thử dùng gói Premium */
a.try-premium.on-premium.btn-primary {
    background-color: #4A3021 !important;
    color: #D2B48C !important;
    border-color: #4A3021 !important;
}

/* Chữ và biểu tượng bên trong nút Premium */
a.try-premium.on-premium.btn-primary,
a.try-premium.on-premium.btn-primary * {
    color: #D2B48C !important;
}

/* Hiệu ứng khi rê chuột */
a.try-premium.on-premium.btn-primary:hover {
    background-color: #65452F !important;
    border-color: #65452F !important;
}
 /* ===== ĐỔI ĐƯỜNG KẺ TRẮNG SANG NÂU ĐẬM ===== */

/* Đường kẻ ngang */
hr {
    border: 0 !important;
    border-top: 1px solid #4A3021 !important;
    height: 0 !important;
    background: transparent !important;
    opacity: 1 !important;
}

/* Đường phân cách được tạo bằng phần tử riêng */
[class*="divider"],
[class*="Divider"],
[class*="separator"],
[class*="Separator"] {
    background-color: #4A3021 !important;
    border-color: #4A3021 !important;
}

/* Không tác động lên đường viền của nút và khung nội dung */
button,
input,
textarea,
a {
    outline-color: #4A3021;
}
}
